inline const ConsumableHand* consumableHand(uint32_t item){
    size_t lo=0,hi=catalogConsumableHands.size();while(lo<hi){const size_t mid=(lo+hi)/2;if(catalogConsumableHands[mid].item<item)lo=mid+1;else hi=mid;}
    return lo<catalogConsumableHands.size()&&catalogConsumableHands[lo].item==item?&catalogConsumableHands[lo]:nullptr;
}
